# Run against the actual package generated by jmvtools::prepare().
# Unlike tests/ci-core.R this exercises .init(), .run() and the result tables.
stopifnot(requireNamespace("validityHTMT", quietly = TRUE))
source("R/htmt-core.R")

d <- utils::read.csv("examples/htmt_example.csv", check.names = FALSE)
groups <- list(
    list(label = "C1", vars = paste0("C1_", 1:4)),
    list(label = "C2", vars = paste0("C2_", 1:4)),
    list(label = "C3", vars = paste0("C3_", 1:4))
)
namedGroups <- lapply(groups, function(x) x$vars)
names(namedGroups) <- vapply(groups, function(x) x$label, "")

execute <- function(method = "pearson", missing = "pairwise",
                    threshold = "liberal90", showPairs = TRUE,
                    data = d, constructs = groups) {
    validityHTMT::discriminantValidity(
        data = data, constructs = constructs, correlation = method,
        missing = missing, threshold = threshold, showPairs = showPairs
    )
}

check <- function(method) {
    analysis <- execute(method = method)
    matrixTable <- analysis$htmtMatrix$asDF
    pairTable <- analysis$pairTable$asDF
    cat("Actual analysis ", method, " matrix:\n", sep = "")
    print(matrixTable)
    cat("Actual analysis pairwise table:\n")
    print(pairTable)
    stopifnot(is.data.frame(matrixTable), nrow(matrixTable) == 3L,
              ncol(matrixTable) == 4L,
              is.data.frame(pairTable), nrow(pairTable) == 3L,
              ncol(pairTable) == 4L)
    calculated <- htmt_matrix(
        d, namedGroups, method = method, use = "pairwise.complete.obs"
    )
    observed <- as.matrix(sapply(matrixTable[-1], as.numeric))
    stopifnot(identical(dim(observed), c(3L, 3L)))
    stopifnot(all(is.na(diag(observed))))
    for (i in seq_len(2)) for (j in seq.int(i + 1, 3)) {
        stopifnot(is.finite(observed[i, j]), is.finite(observed[j, i]),
                  abs(observed[i, j] - calculated[i, j]) < 1e-10,
                  abs(observed[j, i] - calculated[i, j]) < 1e-10)
    }
    stopifnot(identical(as.character(matrixTable[[1]]),
                        c("C1", "C2", "C3")))
    invisible(analysis)
}
check("pearson")
check("spearman")

# Threshold changes must not affect the numeric matrix but must change
# the human-readable classification for an HTMT+ in the interval (.85, .90).
set.seed(843)
n <- 6000
f1 <- stats::rnorm(n)
f2 <- 0.875 * f1 + sqrt(1 - 0.875^2) * stats::rnorm(n)
dd <- data.frame(
    A1 = f1 + stats::rnorm(n, sd = 0.2),
    A2 = f1 + stats::rnorm(n, sd = 0.2),
    B1 = f2 + stats::rnorm(n, sd = 0.2),
    B2 = f2 + stats::rnorm(n, sd = 0.2)
)
gg <- list(list(label = "A", vars = c("A1", "A2")),
           list(label = "B", vars = c("B1", "B2")))
h <- htmt_matrix(dd, list(A = c("A1", "A2"), B = c("B1", "B2")))["A", "B"]
stopifnot(h > .85, h < .90)
strict <- execute(data = dd, constructs = gg, threshold = "strict85")
liberal <- execute(data = dd, constructs = gg, threshold = "liberal90")
strictTab <- strict$pairTable$asDF
liberalTab <- liberal$pairTable$asDF
print(strictTab)
print(liberalTab)
stopifnot(nrow(strictTab) == 1L, nrow(liberalTab) == 1L)
stopifnot(any(grepl("Potential", as.character(unlist(strictTab)),
                   fixed = TRUE)),
          any(grepl("supported", as.character(unlist(liberalTab)),
                    fixed = TRUE)))

# Optional interpretation table must not affect HTMT+ values.
noPairs <- execute(showPairs = FALSE)
stopifnot(nrow(noPairs$htmtMatrix$asDF) == 3L)
# Verify complete-case handling through the generated analysis, not only the core.
incomplete <- d
incomplete$C1_1[1:5] <- NA_real_
incomplete$C2_2[6:10] <- NA_real_
completeResult <- execute(data = incomplete, method = "spearman",
                          missing = "complete")
completeExpected <- htmt_matrix(incomplete, namedGroups,
    method = "spearman", use = "complete.obs")
completeObserved <- as.matrix(sapply(completeResult$htmtMatrix$asDF[-1],
                                     as.numeric))
stopifnot(abs(completeObserved[1, 2] - completeExpected[1, 2]) < 1e-10,
          abs(completeObserved[1, 3] - completeExpected[1, 3]) < 1e-10,
          abs(completeObserved[2, 3] - completeExpected[2, 3]) < 1e-10)

# Exercise the name fallback when a construct has a blank name.
blank <- groups
blank[[3]]$label <- ""
blankResult <- execute(constructs = blank)
stopifnot(identical(as.character(blankResult$htmtMatrix$asDF[[1]]),
                    c("C1", "C2", "Construct 3")))

# A constant indicator should generate a native warning, while still
# allowing usable construct pairs to be reported (no fatal runtime error).
set.seed(109)
warningData <- data.frame(
    A1 = stats::rnorm(60), A2 = stats::rnorm(60),
    B1 = stats::rnorm(60), B2 = stats::rnorm(60),
    C1 = rep(1, 60), C2 = stats::rnorm(60)
)
warningGroups <- list(
    list(label = "A", vars = c("A1", "A2")),
    list(label = "B", vars = c("B1", "B2")),
    list(label = "C", vars = c("C1", "C2"))
)
warnResult <- execute(data = warningData, constructs = warningGroups)
warnMatrix <- warnResult$htmtMatrix$asDF
warnPairs <- warnResult$pairTable$asDF
stopifnot(nrow(warnMatrix) == 3L, nrow(warnPairs) == 3L,
          is.finite(as.numeric(warnMatrix[1, 3])),
          is.na(as.numeric(warnMatrix[1, 4])),
          any(grepl("Not estimable", unlist(warnPairs), fixed = TRUE)))
cat("Non-finite correlation warning path completed without a fatal error.\n")

cat("Packaged jamovi analysis integration checks passed.\n")
